                  }
                  tree.offset <- cumsum(tree.offset)
                  block.offset <- array(1, floor(ntree/block.size))
                  if (floor(ntree/block.size) > 1) {
                    block.offset[2:floor(ntree/block.size)] <- length(regr.index)
                  }
                  block.offset <- cumsum(block.offset)
                  vimp.offset <- array(1, n.xvar)
                  if (n.xvar > 1) {
                    vimp.offset[2:n.xvar] <- length(regr.index)
                  }
                  vimp.offset <- cumsum(vimp.offset)
                  iter.ensb.start <- 0
                  iter.ensb.end <- 0
                  iter.qntl.start <- 0
                  iter.qntl.end <- 0
                  if (!is.null(nativeOutput$holdoutRegr)) {
                    holdout.offset.x <- rfsrcOutput$holdout.blk * resp.regr.count
                    holdout.offset.sum.x <- c(0, cumsum(holdout.offset.x))
                    holdout.offset.r <- 0
                  }
                  for (i in 1:resp.regr.count) {
                    iter.ensb.start <- iter.ensb.end
                    iter.ensb.end <- iter.ensb.end + n
                    iter.qntl.start <- iter.qntl.end
                    iter.qntl.end <- iter.qntl.end + (length(prob) * n)
                    vimp.names <- xvar.names
                    predicted <- (if (!is.null(nativeOutput$allEnsbRGR)) 
                      array(nativeOutput$allEnsbRGR[(iter.ensb.start + 1):iter.ensb.end], n)
                    else NULL)
                    regrOutput[[i]] <- list(predicted = predicted)
                    remove(predicted)
                    predicted.oob <- (if (!is.null(nativeOutput$oobEnsbRGR)) 
                      array(nativeOutput$oobEnsbRGR[(iter.ensb.start + 1):iter.ensb.end], n)
                    else NULL)
                    regrOutput[[i]] <- c(regrOutput[[i]], predicted.oob = list(predicted.oob))
                    remove(predicted.oob)
                    cse.num <- (if (!is.null(nativeOutput$cseRegr)) 
                      array(nativeOutput$cseRegr[(iter.ensb.start + 1):iter.ensb.end], n)
                    else NULL)
                    regrOutput[[i]] <- c(regrOutput[[i]], cse.num = list(cse.num))
                    remove(cse.num)
                    cse.den <- (if (!is.null(nativeOutput$cseDen)) 
                      array(nativeOutput$cseDen[1:n], n)
                    else NULL)
                    regrOutput[[i]] <- c(regrOutput[[i]], cse.den = list(cse.den))
                    quantile <- (if (!is.null(nativeOutput$allEnsbQNT)) 
                      array(nativeOutput$allEnsbQNT[(iter.qntl.start + 1):iter.qntl.end], c(n, length(prob)))
                    else NULL)
                    regrOutput[[i]] <- c(regrOutput[[i]], quantile = list(quantile))
                    remove(quantile)
                    quantile.oob <- (if (!is.null(nativeOutput$oobEnsbQNT)) 
                      array(nativeOutput$oobEnsbQNT[(iter.qntl.start + 1):iter.qntl.end], c(n, length(prob)))
                    else NULL)
                    regrOutput[[i]] <- c(regrOutput[[i]], quantile.oob = list(quantile.oob))
                    remove(quantile.oob)
                    if (!is.null(nativeOutput$perfRegr)) {
                      err.rate <- nativeOutput$perfRegr[tree.offset]
                      tree.offset <- tree.offset + 1
                      regrOutput[[i]] <- c(regrOutput[[i]], err.rate = list(err.rate))
                      remove(err.rate)
                    }
                    if (!is.null(nativeOutput$blockRegr)) {
                      err.block.rate <- nativeOutput$blockRegr[block.offset]
                      block.offset <- block.offset + 1
                      regrOutput[[i]] <- c(regrOutput[[i]], err.block.rate = list(err.block.rate))
                      remove(err.block.rate)
                    }
                    if (!is.null(nativeOutput$vimpRegr)) {
                      importance <- nativeOutput$vimpRegr[vimp.offset]
                      names(importance) <- xvar.names
                      vimp.offset <- vimp.offset + 1
                      regrOutput[[i]] <- c(regrOutput[[i]], importance = list(importance))
                      remove(importance)
                    }
                    csv.idx <- array(0, n * n.xvar)
                    for (j in 1:n.xvar) {
                      csv.idx[(((j - 1) * n) + 1):(((j - 1) * n) + n)] <- (((i - 1) * n) + ((j - 1) * n * 
                        resp.regr.count) + 1):(((i - 1) * n) + ((j - 1) * n * resp.regr.count) + n)
                    }
                    csv.num <- (if (!is.null(nativeOutput$csvRegr)) 
                      array(nativeOutput$csvRegr[csv.idx], c(n, n.xvar))
                    else NULL)
                    regrOutput[[i]] <- c(regrOutput[[i]], csv.num = list(csv.num))
                    remove(csv.num)
                    csv.den <- (if (!is.null(nativeOutput$csvDen)) 
                      array(nativeOutput$csvDen, c(n, n.xvar))
                    else NULL)
                    regrOutput[[i]] <- c(regrOutput[[i]], csv.den = list(csv.den))
                    remove(csv.den)
                    if (!is.null(nativeOutput$holdoutRegr)) {
                      holdout.vimp <- vector("list", length(rfsrcOutput$holdout.blk))
                      names(holdout.vimp) <- xvar.names
                      if (i > 1) {
                        holdout.offset.r <- holdout.offset.r + 1
                      }
                      for (k in 1:length(holdout.vimp)) {
                        if (rfsrcOutput$holdout.blk[k] > 0) {
                          offset.x <- holdout.offset.sum.x[k]
                          offset.b <- 0
                          index.m <- NULL
                          for (m in 1:rfsrcOutput$holdout.blk[k]) {
                            if (m > 1) {
                              offset.b <- offset.b + resp.regr.count
                            }
                            index.m <- c(index.m, offset.x + offset.b + holdout.offset.r + 1)
                          }
                          holdout.vimp[[k]] <- nativeOutput$holdoutRegr[index.m]
                        }
                        else {
                          holdout.vimp[[k]] <- NA
                        }
                      }
                      regrOutput[[i]] <- c(regrOutput[[i]], holdout.vimp = list(holdout.vimp))
                    }
                  }
                  nativeOutput$allEnsbRGR <- NULL
                  nativeOutput$oobEnsbRGR <- NULL
                  nativeOutput$allEnsbQNT <- NULL
                  nativeOutput$oobEnsbQNT <- NULL
                  nativeOutput$perfRegr <- NULL
                  nativeOutput$blockRegr <- NULL
                  nativeOutput$vimpRegr <- NULL
                  nativeOutput$holdoutRegr <- NULL
                  if (univariate.nomenclature) {
                    if ((resp.clas.count == 0) & (resp.regr.count == 1)) {
                      names(regrOutput) <- NULL
                      rfsrcOutput <- c(rfsrcOutput, unlist(regrOutput, recursive = FALSE))
                    }
                    else {
                      rfsrcOutput <- c(rfsrcOutput, regrOutput = list(regrOutput))
                    }
                  }
                  else {
                    rfsrcOutput <- c(rfsrcOutput, regrOutput = list(regrOutput))
                  }
              }
          }
      }
      class(rfsrcOutput) <- c("rfsrc", "grow", family)
      return(rfsrcOutput)
  }
  predict.rfsrc <- function(object, newdata, importance = c(FALSE, TRUE, "none", "anti", "permute", "random"), 
      get.tree = NULL, block.size = if (any(is.element(as.character(importance), c("none", "FALSE")))) NULL else 10, 
      na.action = c("na.omit", "na.impute", "na.random"), outcome = c("train", "test"), perf.type = NULL, 
      proximity = FALSE, forest.wt = FALSE, ptn.count = 0, distance = FALSE, var.used = c(FALSE, "all.trees", 
          "by.tree"), split.depth = c(FALSE, "all.trees", "by.tree"), case.depth = FALSE, seed = NULL, 
      do.trace = FALSE, membership = FALSE, marginal.xvar = NULL, ...) {
      dots <- list(...)
      m.target <- dots$m.target
      dots$m.target <- NULL
      importance.xvar <- dots$importance.xvar
      dots$importance.xvar <- NULL
      args <- c(list(object = object, m.target = m.target, importance = importance, get.tree = get.tree, 
          block.size = block.size, importance.xvar = importance.xvar, na.action = na.action, outcome = outcome, 
          perf.type = perf.type, proximity = proximity, forest.wt = forest.wt, ptn.count = ptn.count, distance = distance, 
          var.used = var.used, split.depth = split.depth, case.depth = case.depth, seed = seed, do.trace = do.trace, 
          membership = membership, marginal.xvar = marginal.xvar), dots)
      if (!missing(newdata)) {
          args$newdata <- newdata
      }
      return(do.call("generic.predict.rfsrc", args))
  }
  distance <- function(x, method = "euclidean", rowI = NULL, rowJ = NULL, do.trace = FALSE) {
      n = dim(x)[1]
      p = dim(x)[2]
      if (n < 2) {
          stop("matrix must have more than one (1) row")
      }
      if (length(rowI) > 0) {
          if (length(rowI) != length(rowJ)) {
              stop("rowI and rowJ identifiers must have the same length")
          }
      }
      method.names <- c("euclidean", "canberra", "maximum")
      if (is.null(method)) {
          method.idx <- which(method.names == "euclidean")
      }
      else {
          method.idx <- which(method.names == method)
      }
      if (length(method.idx) != 1) {
          stop("distance metric invalid")
      }
      nativeOutput <- .Call("sl_rfsrcDistance", as.integer(method.idx), as.integer(n), as.integer(p), as.double(x), 
          as.integer(length(rowI)), as.integer(rowI), as.integer(rowJ), as.integer(get.rf.cores()), as.integer(do.trace), 
          PACKAGE = "survlearning")
      if (is.null(nativeOutput)) {
          stop("An error has occurred in rfsrcDistance.  Please turn trace on for further analysis.")
      }
      if (length(rowI) > 0) {
          result <- list(rowI = rowI, rowJ = rowJ, distance = nativeOutput$distance)
      }
      else {
          result <- matrix(0, n, n)
          count <- 0
          for (k in 2:n) {
              result[k, 1:(k - 1)] <- nativeOutput$distance[(count + 1):(count + k - 1)]
              result[1:(k - 1), k] <- result[k, 1:(k - 1)]
              count <- count + (k - 1)
          }
      }
      return(result)
  }
  generic.predict.rfsrc <- function(object, newdata, m.target = NULL, importance = FALSE, get.tree = NULL, 
      block.size = NULL, importance.xvar, na.action = c("na.omit", "na.impute", "na.random"), outcome = c("train", 
          "test"), perf.type = NULL, proximity = FALSE, forest.wt = FALSE, ptn.count = 0, distance = FALSE, 
      var.used = c(FALSE, "all.trees", "by.tree"), split.depth = c(FALSE, "all.trees", "by.tree"), case.depth = FALSE, 
      seed = NULL, do.trace = FALSE, membership = FALSE, marginal.xvar = NULL, ...) {
      univariate.nomenclature <- TRUE
      user.option <- list(...)
      if (missing(object)) {
          stop("object is missing!")
      }
      if (sum(inherits(object, c("rfsrc", "grow"), TRUE) == c(1, 2)) != 2 & sum(inherits(object, c("rfsrc", 
          "forest"), TRUE) == c(1, 2)) != 2) 
          stop("this function only works for objects of class `(rfsrc, grow)' or '(rfsrc, forest)'")
      if (sum(inherits(object, c("rfsrc", "grow"), TRUE) == c(1, 2)) == 2) {
          if (is.forest.missing(object)) {
              stop("Forest information for prediction is missing.  Re-run rfsrc (grow call) with forest=TRUE")
          }
      }
      cse <- is.hidden.cse(user.option)
      csv <- is.hidden.csv(user.option)
      importance <- match.arg(as.character(importance)[1], c(FALSE, TRUE, "none", "anti", "permute", "random", 
          "anti.joint", "permute.joint", "random.joint"))
      if (grepl("joint", importance)) {
          vimp.joint <- TRUE
      }
      else {
          vimp.joint <- FALSE
      }
      na.action <- match.arg(na.action, c("na.omit", "na.impute", "na.random"))
      if (inherits(object, "anonymous") && na.action == "na.impute") {
          na.action <- "na.mean"
      }
      outcome <- match.arg(outcome, c("train", "test"))
      proximity <- match.arg(as.character(proximity), c(FALSE, TRUE, "inbag", "oob", "all", "hybrid"))
      forest.wt <- match.arg(as.character(forest.wt), c(FALSE, TRUE, "inbag", "oob", "all"))
      distance <- match.arg(as.character(distance), c(FALSE, TRUE, "inbag", "oob", "all", "hybrid"))
      if (missing(newdata)) {
          restore.mode <- TRUE
          outcome <- "train"
          ensemble <- "all"
      }
      else {
          restore.mode <- FALSE
          if (outcome == "test") {
              ensemble <- "all"
          }
          else {
              ensemble <- "inbag"
          }
      }
      if (inherits(object, "anonymous")) {
          anonymize.bits <- 2^26
          outcome <- "train"
          if (restore.mode) {
              stop("in order to predict with anonymous forests please provide a test data set")
          }
      }
      else {
          anonymize.bits <- 0
      }
      jitt <- is.hidden.jitt(user.option, importance, na.action, inherits(object, "anonymous"), partial = FALSE)
      rfq <- is.hidden.rfq(user.option)
      gk.quantile <- is.hidden.gk.quantile(user.option)
      prob <- is.hidden.prob(user.option)
      prob.epsilon <- is.hidden.prob.epsilon(user.option)
      vimp.threshold <- is.hidden.vimp.threshold(user.option)
      family <- object$family
      xvar.names <- object$xvar.names
      yvar.names <- object$yvar.names
      subj.names <- object$subj.names
      importance.xvar <- get.importance.xvar(importance.xvar, importance, object)
      importance.xvar.idx <- match(importance.xvar, xvar.names)
      marginal.xvar <- get.marginal.xvar(marginal.xvar, object)
      marginal.xvar.idx <- NULL
      if (length(marginal.xvar) > 0) {
          marginal.xvar.idx <- match(marginal.xvar, xvar.names)
      }
      var.used <- match.arg(as.character(var.used), c("FALSE", "all.trees", "by.tree"))
      if (var.used == "FALSE") 
          var.used <- FALSE
      split.depth <- match.arg(as.character(split.depth), c("FALSE", "all.trees", "by.tree"))
      if (split.depth == "FALSE") 
          split.depth <- FALSE
      split.depth = FALSE
      seed <- get.seed(seed)
      big.data <- FALSE
      if (sum(inherits(object, c("rfsrc", "grow"), TRUE) == c(1, 2)) == 2) {
          if (inherits(object, "bigdata")) {
              big.data <- TRUE
          }
          object <- object$forest
      }
      else {
          if (inherits(object, "bigdata")) {
              big.data <- TRUE
          }
      }
      if (is.null(object$version)) {
          cat("\n  This function only works with objects created with the following minimum version of the package:")
          cat("\n    Minimum version:  ")
          cat("2.3.0")
          cat("\n    Your version:     ")
          cat("unknown")
          cat("\n")
          stop()
      }
      else {
          object.version <- as.integer(unlist(strsplit(object$version, "[.]")))
          installed.version <- as.integer(unlist(strsplit("3.9.0", "[.]")))
          minimum.version <- as.integer(unlist(strsplit("2.3.0", "[.]")))
          object.version.adj <- object.version[1] + (object.version[2]/10) + (object.version[3]/100)
          installed.version.adj <- installed.version[1] + (installed.version[2]/10) + (installed.version[3]/100)
          minimum.version.adj <- minimum.version[1] + (minimum.version[2]/10) + (minimum.version[3]/100)
          if (object.version.adj >= minimum.version.adj) {
          }
          else {
              cat("\n  This function only works with objects created with the following minimum version of the package:")
              cat("\n    Minimum version:  ")
              cat("2.3.0")
              cat("\n    Your version:     ")
              cat(object$version)
              cat("\n")
              stop()
          }
      }
      class.relfrq <- NULL
      if (family == "class") {
          if (!is.null(rfq)) {
              if (!rfq) {
              }
              else {
                  class.relfrq <- prop.table(table(object$yvar))
              }
          }
          if (is.null(rfq)) {
              if (!object$rfq) {
              }
              else {
                  class.relfrq <- prop.table(table(object$yvar))
                  rfq <- TRUE
              }
          }
          if (is.null(perf.type) && !is.null(object$perf.type)) {
              perf.type <- object$perf.type
          }
      }
      splitrule <- object$splitrule
      if (!is.null(gk.quantile) || object$gk.quantile) {
          if (is.null(gk.quantile)) {
              gk.quantile <- object$gk.quantile
          }
      }
      gk.quantile <- get.gk.quantile(gk.quantile)
      prob.assign <- global.prob.assign(if (is.null(prob)) 
          object$prob
      else prob, if (is.null(prob.epsilon)) 
          object$prob.epsilon
      else prob.epsilon, gk.quantile, object$quantile.regr, splitrule, object$n)
      prob <- prob.assign$prob
      prob.epsilon <- prob.assign$prob.epsilon
      yfactor <- object$yvar.factor
      m.target.idx <- get.outcome.target(family, yvar.names, m.target)
      yvar.types <- yfactor$types
      yvar.nlevels <- yfactor$nlevels
      yvar.numeric.levels <- yfactor$numeric.levels
      subj <- object$subj
      event.info <- object$event.info
      event.type <- event.info$event.type
      cr.bits <- get.cr.bits(family)
      xfactor <- object$xvar.factor
      any.xvar.factor <- (length(xfactor$factor) + length(xfactor$order)) > 0
      xvar.types <- xfactor$types
      xvar.nlevels <- xfactor$nlevels
      xvar.numeric.levels <- xfactor$numeric.levels
      n.xvar <- length(xvar.names)
      n <- object$n
      r.dim <- event.info$rdim
      if (family == "unsupv") {
          outcome <- "train"
          perf.type <- "none"
          importance <- "none"
      }
      if (grepl("surv", family)) {
          ptn.count <- 0
      }
      uno.weights.test <- NULL
      use.uno <- !is.null(object$uno.weights)
      if (!is.null(user.option$use.uno) && isFALSE(user.option$use.uno)) {
          use.uno <- FALSE
      }
      if (!is.null(user.option$use.uno) && isTRUE(user.option$use.uno)) {
          use.uno <- TRUE
      }
      if (!restore.mode) {
          if (!identical(class(newdata), "data.frame")) {
              newdata <- as.data.frame(newdata, optional = TRUE)
          }
          newdata <- newdata[, is.element(names(newdata), c(yvar.names, xvar.names)), drop = FALSE]
          if (inherits(object, "anonymous") && na.action == "na.mean") {
              newdata <- assign.impute.mean(newdata, object$impute.mean)
              na.action <- "na.omit"
          }
          newdata <- rm.na.levels(newdata, xvar.names)
          any.outcome.factor <- family == "class"
          if (family == "class+" | family == "mix+") {
              if (length(intersect("R", yfactor$generic.types[m.target.idx])) == 0) {
                  any.outcome.factor <- TRUE
              }
          }
          if (any.outcome.factor) {
              if (sum(is.element(names(newdata), yvar.names)) > 0) {
                  newdata <- rm.na.levels(newdata, yvar.names)
              }
          }
          if (length(xvar.names) != sum(is.element(xvar.names, names(newdata)))) {
              stop("x-variables in test data do not match original training data")
          }
          yvar.present <- sum(is.element(yvar.names, names(newdata))) > 0
          if (yvar.present && length(yvar.names) != sum(is.element(yvar.names, names(newdata)))) {
              stop("y-variables in test data do not match original training data")
          }
          if (any.xvar.factor) {
              newdata <- check.factor(newdata, xfactor)
          }
          if (any.outcome.factor) {
              if (yvar.present) {
                  newdata <- check.factor(newdata, yfactor, ignore = TRUE)
              }
          }
          if (yvar.present) {
              fnames <- c(yvar.names, xvar.names)
          }
          else {
              fnames <- xvar.names
          }
          newdata <- finalizeData(fnames, newdata, na.action)
          xvar.newdata <- as.matrix(newdata[, xvar.names, drop = FALSE])
          n.newdata <- nrow(newdata)
          newdata.row.names <- rownames(xvar.newdata)
          if (yvar.present) {
              yvar.newdata <- as.matrix(newdata[, yvar.names, drop = FALSE])
              event.info.newdata <- get.grow.event.info(yvar.newdata, family, need.deaths = FALSE)
              r.dim.newdata <- event.info.newdata$r.dim
              if (grepl("surv", family) && all(na.omit(event.info.newdata$cens) == 0)) {
                  perf.type <- "none"
                  importance <- "none"
              }
              if (grepl("surv", family) && length(setdiff(na.omit(event.info.newdata$cens), na.omit(event.info$cens))) > 
                  1) {
                  stop("survival events in test data do not match training data")
              }
              if (!is.null(object$uno.weights) && isTRUE(use.uno)) {
                  uno.weights.test <- uno.prepare.test(yvar.newdata[, 1], yvar.newdata[, 2], object$uno.weights$fit)$weight
              }
              if (is.null(object$uno.weights) && isTRUE(use.uno)) {
                  uno.weights.fit <- get.uno.weights.train(object$event.info$time, object$event.info$cens)$fit
                  uno.weights.test <- uno.prepare.test(yvar.newdata[, 1], yvar.newdata[, 2], uno.weights.fit)$weight
              }
          }
          else {
              if (outcome == "test") {
                  stop("outcome=TEST, but the test data has no y values, which is not permitted")
              }
              r.dim.newdata <- 0
              yvar.newdata <- NULL
              perf.type <- "none"
              importance <- "none"
          }
          if (outcome != "test") {
              rownames(xvar.newdata) <- colnames(xvar.newdata) <- NULL
          }
          remove(newdata)
      }
      else {
          n.newdata <- 0
          r.dim.newdata <- 0
          xvar.newdata <- NULL
          yvar.newdata <- NULL
          outcome <- "train"
          if (object$bootstrap == "none" || object$bootstrap == "by.node" || family == "unsupv") {
              importance <- "none"
              perf.type <- "none"
          }
          else {
          }
          if (is.null(user.option$vimp.threshold)) {
              vimp.threshold <- object$vimp.threshold
          }
          if (!is.null(object$uno.weights) && isTRUE(use.uno)) {
              uno.weights.test <- object$uno.weights$weight
          }
          if (is.null(object$uno.weights) && isTRUE(use.uno)) {
              uno.weights.test <- get.uno.weights.train(object$event.info$time, object$event.info$cens)$weight
          }
      }
      if (outcome == "train") {
          yvar <- as.matrix(data.matrix(data.frame(object$yvar)))
          sampsize <- round(object$sampsize(n))
          case.wt <- object$case.wt
          samp <- object$samp
          if (anonymize.bits == 0) {
              xvar <- as.matrix(data.matrix(object$xvar))
              rownames(xvar) <- colnames(xvar) <- NULL
          }
          else {
              xvar <- NULL
          }
      }
      if (outcome == "test") {
          xvar <- xvar.newdata
          yvar <- yvar.newdata
          rownames(xvar) <- colnames(xvar) <- NULL
          restore.mode <- TRUE
          n <- nrow(xvar)
          r.dim <- r.dim.newdata
          n.newdata <- 0
          r.dim.newdata <- 0
          sampsize <- round(object$sampsize(n))
          case.wt <- get.weight(NULL, n)
          samp <- NULL
      }
      ntree <- object$ntree
      get.tree <- get.tree.index(get.tree, ntree)
      perf.type <- get.perf(perf.type, FALSE, family)
      perf.bits <- get.perf.bits(perf.type)
      rfq <- get.rfq(rfq)
      rfq.bits <- get.rfq.bits(rfq, family)
      gk.quantile.bits <- get.gk.quantile.bits(gk.quantile)
      bootstrap.bits <- get.bootstrap.bits(object$bootstrap)
      ensemble.bits <- get.ensemble.bits(ensemble)
      importance.bits <- get.importance.bits(importance, perf.type)
      proximity.bits <- get.proximity.bits(restore.mode, proximity)
      distance.bits <- get.distance.bits(restore.mode, distance)
      split.depth.bits <- get.split.depth.bits(split.depth)
      var.used.bits <- get.var.used.bits(var.used)
      outcome.bits <- get.outcome.bits(outcome)
      case.depth.bits <- get.case.depth.bits(case.depth)
      samptype.bits <- get.samptype.bits(object$samptype)
