  get.perf <- function(perf, impute.only, family) {
      if (impute.only == TRUE) {
          return("none")
      }
      if (family != "class") {
          if (is.null(perf)) {
              return("default")
          }
          perf <- match.arg(perf, c("none", "default", "standard"))
          if (perf == "standard") {
              perf <- "default"
          }
          return(perf)
      }
      if (is.null(perf)) {
          return("default")
      }
      perf <- match.arg(perf, c("none", "default", "standard", "misclass", "brier", "gmean", "g.mean"))
      if (perf == "standard" || perf == "misclass") {
          perf <- "default"
      }
      if (perf == "g.mean") {
          perf <- "gmean"
      }
      perf
  }
  get.perf.bits <- function(perf) {
      if (perf == "default") {
          return(2^2)
      }
      else if (perf == "gmean" || perf == "g.mean") {
          return(2^2 + 2^14)
      }
      else if (perf == "brier") {
          return(2^2 + 2^3)
      }
      else {
          return(0)
      }
  }
