                  prox.bits <- 2^28 + 2^30
              }
              else if (proximity == "all") {
                  prox.bits <- 2^28 + 2^30
              }
              else if (proximity == "hybrid") {
                  prox.bits <- 2^28 + 2^29 + 2^30
              }
              else {
                  stop("Invalid choice for 'proximity' option:  ", proximity)
              }
          }
          else {
              stop("Invalid choice for 'grow.equivalent' in proximity:  ", grow.equivalent)
