  get.tdc.rule.bits <- function(tdc.rule) {
      if (is.null(tdc.rule)) {
          result <- 2^24 + 2^25 + 2^26
      }
      else if (tdc.rule == "all") {
          result <- 2^24 + 2^25 + 2^26
      }
      else if (tdc.rule == "time") {
          result <- 2^24
      }
      else if (tdc.rule == "tdx") {
          result <- 2^25
      }
      else if (tdc.rule == "tsx") {
          result <- 2^26
      }
      else if (tdc.rule == "time.and.tsx") {
          result <- 2^24 + 2^26
      }
      else if (tdc.rule == "time.and.tdx") {
          result <- 2^24 + 2^25
      }
      return(result)
  }
