  adrop3d.last <- function(x, d, keepColNames = FALSE) {
      if (!is.array(x)) {
          x
      }
      else {
          if (d > 1) {
              x[, , 1:d, drop = FALSE]
          }
          else {
              if (dim(x)[1] == 1) {
                  rbind(x[, , 1, drop = TRUE])
              }
              else {
                  if (dim(x)[2] == 1) {
                    if (keepColNames) {
                      xnew <- cbind(x[, , 1, drop = TRUE])
                      colnames(xnew) <- colnames(x)
                      xnew
                    }
                    else {
                      cbind(x[, , 1, drop = TRUE])
                    }
                  }
                  else {
                    x[, , 1, drop = TRUE]
                  }
              }
          }
      }
  }
