  get.numeric.levels <- function(fmly, nlevels, gvar) {
      gvar.numeric.levels <- lapply(1:length(nlevels), function(nn) {
          if (nlevels[nn] > 0) 
              unique(sort(gvar[, nn]))
          else NULL
