  global.prob.assign <- function(prob, prob.epsilon, gk.quantile, quantile.regr, splitrule, n) {
      prob.default <- (1:99)/100
      prob.epsilon.default <- 0.005
      prob.bs.default <- 0.9
      if (quantile.regr || grepl("quantile.regr", splitrule) || gk.quantile) {
          if (!is.null(prob)) {
              if (!is.numeric(prob) || !is.null(dim(prob)) || !length(prob) || any(!is.finite(prob))) {
                  stop("parameter 'prob' must be a nonempty finite numeric vector")
              }
              prob <- sort(prob[prob > 0 & prob < 1])
              if (!length(prob)) 
                  stop("parameter 'prob' is not between (0,1)")
          }
          if (gk.quantile) {
              if (is.null(prob) && is.null(prob.epsilon)) {
                  n <- max(n, 1)
                  prob <- (1:(2 * n))/(2 * n + 1)
                  prob.epsilon <- diff(prob)[1] * 0.99
              }
              else if (is.null(prob) && !is.null(prob.epsilon)) {
                  prob <- prob.default
              }
              else if (!is.null(prob) && is.null(prob.epsilon)) {
                  spacing <- diff(prob)
                  prob.epsilon <- if (length(spacing) && any(spacing > 0)) {
                    mean(spacing) * 0.99
                  }
                  else {
                    prob.epsilon.default
                  }
              }
              else {
              }
          }
          else {
              prob.epsilon <- prob.epsilon.default
              if (is.null(prob)) {
                  prob <- prob.default
              }
          }
          if (gk.quantile && (!is.numeric(prob.epsilon) || length(prob.epsilon) != 1L || !is.finite(prob.epsilon) || 
              prob.epsilon <= 0 || prob.epsilon >= 1)) {
              stop("parameter 'prob.epsilon' must be a finite number in (0,1)")
          }
          if (sum(prob > 0 & prob < 1) == 0) {
              stop("parameter 'prob' is not between (0,1)", prob)
          }
          prob <- sort(prob[prob > 0 & prob < 1])
      }
      if (splitrule == "bs.gradient") {
          if (is.null(prob)) {
              prob <- prob.bs.default
          }
          if (sum(prob > 0 & prob < 1) == 0) {
              stop("parameter 'prob' is not between (0,1)", prob)
          }
          prob <- prob[prob > 0 & prob < 1][1]
      }
      return(list(prob = prob, prob.epsilon = prob.epsilon))
  }
  make.samplesize.function <- function(fraction = 1) {
      f <- paste("x * ", paste(eval(fraction)))
      expr <- parse(text = f)
      function(x) eval(expr, list(x = x))
  }
  parseFormula <- function(f, data, ytry = NULL, coerce.factor = NULL) {
      if (!inherits(f, "formula")) {
          stop("'formula' is not a formula object.")
      }
      if (is.null(data)) {
          stop("'data' is missing.")
      }
      if (!is.data.frame(data)) {
          stop("'data' must be a data frame.")
      }
      fmly <- all.names(f, max.names = 1e+07)[2]
      all.names <- all.vars(f, max.names = 1e+07)
      yvar.names <- all.vars(formula(paste(as.character(f)[2], "~ .")), max.names = 1e+07)
      yvar.names <- yvar.names[-length(yvar.names)]
      subj.names <- NULL
      coerce.factor.org <- coerce.factor
      coerce.factor <- vector("list", 2)
      names(coerce.factor) <- c("xvar.names", "yvar.names")
      if (!is.null(coerce.factor.org)) {
          coerce.factor$yvar.names <- intersect(yvar.names, coerce.factor.org)
          if (length(coerce.factor$yvar.names) == 0) {
              coerce.factor$yvar.names <- NULL
          }
          coerce.factor$xvar.names <- intersect(setdiff(colnames(data), yvar.names), coerce.factor.org)
      }
      if (fmly == "Surv") {
          if ((sum(is.element(yvar.names, names(data))) != 2) && (sum(is.element(yvar.names, names(data))) != 
              4)) {
              stop("Survival formula incorrectly specified.")
          }
          else {
              if (sum(is.element(yvar.names, names(data))) == 4) {
                  subj.names <- yvar.names[1]
                  yvar.names <- yvar.names[-1]
              }
          }
          family <- "surv"
          ytry <- 0
      }
      else if ((fmly == "Multivar" || fmly == "cbind") && length(yvar.names) > 1) {
          if (sum(is.element(yvar.names, names(data))) < length(yvar.names)) {
              stop("Multivariate formula incorrectly specified: y's listed in formula are not in data.")
          }
          Y <- data[, yvar.names, drop = FALSE]
          logical.names <- unlist(lapply(Y, is.logical))
          if (sum(logical.names) > 0) {
              Y[, logical.names] <- 1 * Y[, logical.names, drop = FALSE]
          }
          if ((sum(unlist(lapply(Y, is.factor))) + length(coerce.factor$yvar.names)) == length(yvar.names)) {
              family <- "class+"
          }
          else if ((sum(unlist(lapply(Y, is.factor))) + length(coerce.factor$yvar.names)) == 0) {
              family <- "regr+"
          }
          else if (((sum(unlist(lapply(Y, is.factor))) + length(coerce.factor$yvar.names)) > 0) && ((sum(unlist(lapply(Y, 
              is.factor))) + length(coerce.factor$yvar.names)) < length(yvar.names))) {
              family <- "mix+"
          }
          else {
              stop("y-outcomes must be either real or factors in multivariate forests.")
          }
          if (!is.null(ytry)) {
              if ((ytry < 1) || (ytry > length(yvar.names))) {
                  stop("invalid value for ytry:  ", ytry)
              }
          }
          else {
              ytry <- length(yvar.names)
          }
      }
      else if (fmly == "Unsupervised") {
          if (length(yvar.names) != 0) {
              stop("Unsupervised forests require no y-responses")
          }
          family <- "unsupv"
          yvar.names <- NULL
          temp <- gsub(fmly, "", as.character(f)[2])
          temp <- gsub("\\(|\\)", "", temp)
          ytry <- as.integer(temp)
          if (is.na(ytry)) {
              ytry <- 1
          }
          else {
              if (ytry <= 0) {
                  stop("Unsupervised forests require positive ytry value")
              }
          }
      }
      else {
          if (sum(is.element(yvar.names, names(data))) != 1) {
              stop("formula is incorrectly specified.")
          }
          Y <- data[, yvar.names]
          if (is.logical(Y)) {
              Y <- as.numeric(Y)
          }
          if (!(is.factor(Y) | is.numeric(Y))) {
              stop("the y-outcome must be either real or a factor.")
          }
          if (is.factor(Y) || length(coerce.factor$yvar.names) == 1) {
              family <- "class"
          }
          else {
              family <- "regr"
          }
          ytry <- 1
      }
      return(list(all.names = all.names, family = family, subj.names = subj.names, yvar.names = yvar.names, 
          ytry = ytry, coerce.factor = coerce.factor))
  }
  parseMissingData <- function(formula.obj, data) {
      yvar.names <- formula.obj$yvar.names
      if (length(yvar.names) > 0) {
          resp <- data[, yvar.names, drop = FALSE]
          col.resp.na <- unlist(lapply(data[, yvar.names, drop = FALSE], is.all.na))
          if (any(col.resp.na)) {
              stop("All records are missing for one (or more) yvar(s)")
          }
      }
      colPt <- unlist(lapply(data, is.all.na))
      if (sum(colPt) > 0 && sum(colPt) >= (ncol(data) - length(yvar.names))) {
          stop("All x-variables have all missing data:  analysis not meaningful.")
      }
      data <- data[, !colPt, drop = FALSE]
      rowPt <- apply(data, 1, is.all.na)
      if (sum(rowPt) == nrow(data)) {
          stop("Rows of the data have all missing data:  analysis not meaningful.")
      }
      data <- data[!rowPt, , drop = FALSE]
      return(data)
  }
  extract.factor <- function(dat, generic.names = NULL) {
      generic.types <- gfactor <- gfactor.order <- gfactor.levels <- gfactor.order.levels <- NULL
      target.names <- if (is.null(generic.names)) 
          names(dat)
      else generic.names
      nlevels <- rep(0, length(target.names))
      gfactor <- names(dat)[vapply(dat, is.factor.not.ordered, logical(1))]
      gfactor.order <- names(dat)[vapply(dat, is.ordered, logical(1))]
      if (!is.null(generic.names)) {
          gfactor <- intersect(gfactor, generic.names)
          gfactor.order <- intersect(gfactor.order, generic.names)
      }
      if (length(gfactor) > 0) {
          gfactor.levels <- lapply(gfactor, function(nm) levels(dat[[nm]]))
          nlevels[match(gfactor, target.names)] <- lengths(gfactor.levels)
      }
      if (length(gfactor.order) > 0) {
          gfactor.order.levels <- lapply(gfactor.order, function(nm) levels(dat[[nm]]))
          nlevels[match(gfactor.order, target.names)] <- lengths(gfactor.order.levels)
      }
      if (!is.null(generic.names)) {
          generic.types <- rep("R", length(generic.names))
          if (length(gfactor) > 0) {
              generic.types[match(gfactor, generic.names)] <- "C"
          }
          if (length(gfactor.order) > 0) {
              generic.types[match(gfactor.order, generic.names)] <- "I"
          }
      }
      else {
          generic.types <- rep("R", ncol(dat))
          if (length(gfactor) > 0) {
              generic.types[match(gfactor, names(dat))] <- "C"
          }
          if (length(gfactor.order) > 0) {
              generic.types[match(gfactor.order, names(dat))] <- "I"
          }
      }
      if (is.null(gfactor) & is.null(gfactor.order)) {
          return(NULL)
      }
      else {
          return(list(factor = gfactor, order = gfactor.order, levels = gfactor.levels, order.levels = gfactor.order.levels, 
              nlevels = nlevels, generic.types = generic.types))
      }
  }
  map.factor <- function(gvar, gfactor) {
      if (is.null(gfactor)) 
          return(gvar)
      cn <- colnames(gvar)
      if (length(gfactor$factor) > 0) {
          idx <- match(gfactor$factor, cn)
          new_cols <- lapply(seq_along(idx), function(k) {
              j <- idx[k]
              levs <- gfactor$levels[[k]]
              codes <- gvar[[j]]
              factor.k <- levs[codes]
              labels.k <- levs[sort(unique(codes))]
              gk <- factor(factor.k, labels = labels.k, levels = labels.k, exclude = NULL)
              if (length(setdiff(levs, labels.k)) > 0) {
                  gk <- factor(as.character(gk), levels = levs)
              }
              gk
          })
          gvar[idx] <- new_cols
      }
      if (length(gfactor$order) > 0) {
          idx <- match(gfactor$order, cn)
          new_cols <- lapply(seq_along(idx), function(k) {
              j <- idx[k]
              levs <- gfactor$order.levels[[k]]
              codes <- gvar[[j]]
              factor.k <- levs[codes]
              labels.k <- levs[sort(unique(codes))]
              gk <- factor(factor.k, labels = labels.k, levels = labels.k, exclude = NULL, ordered = TRUE)
              if (length(setdiff(levs, labels.k)) > 0) {
                  gk <- factor(as.character(gk), levels = levs, ordered = TRUE)
              }
              gk
          })
          gvar[idx] <- new_cols
      }
      gvar
  }
  rm.na.levels <- function(dat, xvar.names = NULL) {
      factor.names <- names(dat)[vapply(dat, is.factor, logical(1))]
      if (!is.null(xvar.names)) 
          factor.names <- intersect(factor.names, xvar.names)
      if (length(factor.names) > 0) {
          levels.na.pt <- vapply(factor.names, function(nm) {
              any(levels(dat[[nm]]) == "NA", na.rm = TRUE)
          }, logical(1))
          if (any(levels.na.pt)) {
              fn <- factor.names[levels.na.pt]
              idx <- match(fn, names(dat))
              new_cols <- lapply(fn, function(nm) {
                  x <- dat[[nm]]
                  levels(x)[levels(x) == "NA"] <- NA
                  x
              })
              dat[idx] <- new_cols
          }
      }
      dat
  }
  get.bayes.rule <- function(prob, class.relfrq = NULL) {
      class.labels <- colnames(prob)
      if (is.null(class.relfrq)) {
          factor(class.labels[apply(prob, 1, function(x) {
              if (!all(is.na(x))) {
                  resample(which(x == max(x, na.rm = TRUE)), 1)
              }
              else {
                  NA
              }
          })], levels = class.labels)
      }
      else {
          minority <- which.min(class.relfrq)
          majority <- setdiff(1:2, minority)
          rfq.rule <- rep(majority, nrow(prob))
          rfq.rule[prob[, minority] >= min(class.relfrq, na.rm = TRUE)] <- minority
          factor(class.labels[rfq.rule], levels = class.labels)
      }
  }
  get.grow.event.info <- function(yvar, fmly, need.deaths = TRUE, ntime = NULL) {
      if (grepl("surv", fmly)) {
          if (dim(yvar)[2] == 2) {
              r.dim <- 2
              time <- yvar[, 1]
              cens <- yvar[, 2]
              start.time <- NULL
              if (!all(floor(cens) == abs(cens), na.rm = TRUE)) {
                  stop("for survival families censoring variable must be coded as a non-negative integer (perhaps the formula is set incorrectly?)")
              }
              if (need.deaths && (all(na.omit(cens) == 0))) {
                  stop("no deaths in data!")
              }
              event.type <- unique(na.omit(cens))
              if (sum(event.type >= 0) != length(event.type)) {
                  stop("censoring variable must be coded as NA, 0, or greater than 0.")
              }
              event <- na.omit(cens)[na.omit(cens) > 0]
              event.type <- unique(event)
              nonMissingOutcome <- which(!is.na(cens) & !is.na(time))
              nonMissingDeathFlag <- (cens[nonMissingOutcome] != 0)
              time.interest <- sort(unique(time[nonMissingOutcome[nonMissingDeathFlag]]))
              if (!is.null(ntime) && !((length(ntime) == 1) && ntime == 0)) {
                  if (length(ntime) == 1 && length(time.interest) > ntime) {
                    time.interest <- time.interest[unique(round(seq.int(1, length(time.interest), length.out = ntime)))]
                  }
                  if (length(ntime) > 1) {
                    time.interest <- unique(sapply(ntime, function(tt) {
                      time.interest[max(1, sum(tt >= time.interest, na.rm = TRUE))]
                    }))
                  }
              }
          }
          else {
              r.dim <- 3
              start.time <- yvar[, 1]
              time <- yvar[, 2]
              cens <- yvar[, 3]
              if (!all(floor(cens) == abs(cens), na.rm = TRUE)) {
                  stop("for survival families censoring variable must be coded as a non-negative integer (perhaps the formula is set incorrectly?)")
              }
              if (need.deaths && (all(na.omit(cens) == 0))) {
                  stop("no deaths in data!")
              }
              if (!all(na.omit(time) >= 0)) {
                  stop("time must be  positive")
              }
              event.type <- unique(na.omit(cens))
              if (sum(event.type >= 0) != length(event.type)) {
                  stop("censoring variable must be coded as NA, 0, or greater than 0.")
              }
              event <- na.omit(cens)[na.omit(cens) > 0]
              event.type <- unique(event)
              nonMissingOutcome <- which(!is.na(cens) & !is.na(time))
              nonMissingDeathFlag <- (cens[nonMissingOutcome] != 0)
              time.interest <- sort(unique(time[nonMissingOutcome[nonMissingDeathFlag]]))
              if (!is.null(ntime) && !((length(ntime) == 1) && ntime == 0)) {
                  if (length(ntime) == 1 && length(time.interest) > ntime) {
                    time.interest <- seq(0, min(1, max(time[nonMissingOutcome])), length = ntime)
                    time.interest <- time.interest[time.interest > 0]
                  }
                  if (length(ntime) > 1) {
                    time.pt <- ntime <= min(1, max(time[nonMissingOutcome])) & ntime > 0
                    if (sum(time.pt) == 0) {
                      stop("the ntime vector supplied must be between [0,1]:", ntime)
                    }
                    time.interest <- sort(unique(ntime[time.pt]))
                  }
              }
          }
      }
      else {
          if ((fmly == "regr+") | (fmly == "class+") | (fmly == "mix+")) {
              r.dim <- dim(yvar)[2]
          }
          else {
              if (fmly == "unsupv") {
                  r.dim <- 0
              }
              else {
                  r.dim <- 1
              }
          }
          event <- event.type <- cens <- time.interest <- cens <- time <- start.time <- NULL
      }
      return(list(event = event, event.type = event.type, cens = cens, time.interest = time.interest, time = time, 
          start.time = start.time, r.dim = r.dim))
  }
  get.uno.weights.train <- function(time, status, gmin = "auto", ess_frac = 0.2, ess_min = 20L, eps = 1e-12, 
      eps_keep = .Machine$double.eps, drop_if_G0 = FALSE, return_fit = TRUE) {
      stopifnot(length(time) == length(status))
      fit <- km_censor_fit(time, status)
      G_gate <- uno_Ghat_minus_predict(fit$time, fit$G, time)
      if (is.character(gmin)) {
          gmin <- match.arg(gmin, c("auto", "none"))
          if (gmin == "none") {
              gmin_used <- 0
              ginfo <- list(gmin = 0)
          }
          else {
              ev <- !is.na(status) & (as.integer(status) != 0L) & !is.na(G_gate)
              ginfo <- uno_choose_gmin_auto(G_gate[ev], eps = eps, ess_frac = ess_frac, ess_min = ess_min)
              gmin_used <- ginfo$gmin
          }
      }
      else {
          gmin_used <- as.numeric(gmin)[1L]
          if (!is.finite(gmin_used) || gmin_used < 0) 
              gmin_used <- 0
          ginfo <- list(gmin = gmin_used)
      }
      miss <- is.na(time) | is.na(status)
      G_gate[miss] <- NA_real_
      w <- rep(0, length(time))
      ok <- !is.na(G_gate)
      if (!drop_if_G0) {
          keep <- ok & (G_gate >= gmin_used)
          drop <- ok & !keep
          if (any(keep)) {
              Gsafe <- pmax(G_gate[keep], eps)
              w[keep] <- 1/(Gsafe * Gsafe)
          }
          if (any(drop)) {
              w[drop] <- eps_keep
          }
      }
      else {
          keep <- ok & (G_gate >= gmin_used) & (G_gate > eps)
          drop <- ok & !keep
          if (any(keep)) {
              Gsafe <- pmax(G_gate[keep], eps)
              w[keep] <- 1/(Gsafe * Gsafe)
          }
          if (any(drop)) {
              w[drop] <- eps_keep
          }
      }
      fit$gmin <- gmin_used
      fit$eps_keep <- eps_keep
      fit$gmin_info <- ginfo
      if (return_fit) {
          return(list(weight = w, Ghat_minus = G_gate, fit = fit))
      }
      w
  }
  holdout.vimp.rfsrc <- function(formula, data, ntree = function(p, vtry) {
      1000 * p/vtry
  }, nsplit = 10, ntime = 50, sampsize = function(x) {
      x * 0.632
  }, samptype = "swor", block.size = 10, vtry = 1, ...) {
      dots <- list(...)
      dots$formula <- dots$data <- dots$ntree <- dots$nsplit <- dots$ntime <- dots$samp <- dots$sampsize <- dots$samptype <- dots$block.size <- dots$importance <- NULL
      dots$terminal.qualts <- FALSE
      p <- length(rfsrc(formula, data, nodedepth = 1, ntime = 1, ntree = 1, splitrule = "random")$xvar.names)
      if (!is.function(ntree) && !is.numeric(ntree)) {
          stop("ntree must be a function or number specifying requested number of grow trees")
      }
      if (is.function(ntree)) {
          if (!is.list(vtry)) {
              ntree <- ntree(p, vtry)
          }
          else {
              xvar <- unlist(vtry[1])
              if (any(xvar < 1) | any(xvar > p)) {
                  stop("x-variables specified in vtry should be integer values between 1 and p=number of features")
              }
              joint <- unlist(vtry[2])
              if (!is.logical(joint)) {
                  stop("joint vimp in vtry must be specified as being either TRUE or FALSE")
              }
              if (!joint) {
                  ntree <- ntree(length(xvar), 1)
              }
              else {
                  if (length(xvar) == p) {
                    stop("number of hold out variables for joint analysis must be less than number of features")
                  }
                  ntree <- ntree(1, 1)
              }
          }
      }
      holdout.specs <- get.holdout.specs(vtry, p, ntree, block.size, mode = "baseline")
      seed <- dots$seed
      dots$seed <- NULL
      seed <- get.seed(seed)
      base.obj <- do.call(rfsrc, c(list(formula = formula, data = data, ntree = ntree, nsplit = nsplit, 
          ntime = ntime, sampsize = sampsize, samptype = samptype, holdout.specs = holdout.specs, importance = FALSE, 
          forest = FALSE, terminal.qualts = FALSE, seed = seed), dots))
      holdout.specs <- switch.holdout.specs(holdout.specs, "holdout")
      hold.obj <- do.call(rfsrc, c(list(formula = formula, data = data, ntree = ntree, nsplit = nsplit, 
          ntime = ntime, sampsize = sampsize, samptype = samptype, holdout.specs = holdout.specs, importance = FALSE, 
          forest = FALSE, terminal.qualts = FALSE, seed = seed), dots))
      mv.flag <- FALSE
      if ((class(base.obj)[3] == "regr+") | (class(base.obj)[3] == "class+") | (class(base.obj)[3] == "mix+")) {
          mv.flag <- TRUE
          hvimp <- list()
          if (length(base.obj$regrOutput) > 0) {
              hvimp$regrOutput <- lapply(1:length(base.obj$regrOutput), function(i) {
                  hv <- sapply(1:length(base.obj$regrOutput[[i]]$holdout.vimp), function(j) {
                    mean(hold.obj$regrOutput[[i]]$holdout.vimp[[j]] - base.obj$regrOutput[[i]]$holdout.vimp[[j]], 
                      na.rm = TRUE)
                  })
                  names(hv) <- names(base.obj$regrOutput[[i]]$holdout.vimp)
                  hv
              })
              names(hvimp$regrOutput) <- names(base.obj$regrOutput)
          }
          if (length(base.obj$classOutput) > 0) {
              hvimp$classOutput <- lapply(1:length(base.obj$classOutput), function(i) {
                  yval.i <- colnames(base.obj$classOutput[[i]]$predicted)
                  hv <- do.call(rbind, lapply(1:length(base.obj$classOutput[[i]]$holdout.vimp), function(j) {
                    if (!is.null(dim(base.obj$classOutput[[i]]$holdout.vimp[[j]]))) {
                      rowMeans(hold.obj$classOutput[[i]]$holdout.vimp[[j]] - base.obj$classOutput[[i]]$holdout.vimp[[j]], 
                        na.rm = TRUE)
                    }
                    else {
                      rep(NA, length(yval.i) + 1)
                    }
                  }))
                  colnames(hv) <- c("all", yval.i)
                  rownames(hv) <- names(base.obj$classOutput[[i]]$holdout.vimp)
                  hv
              })
              names(hvimp$classOutput) <- names(base.obj$classOutput)
          }
      }
      else if (class(base.obj)[3] == "regr") {
          hvimp <- sapply(1:length(base.obj$holdout.vimp), function(j) {
              if (!is.null(base.obj$holdout.vimp[[j]])) {
                  mean(hold.obj$holdout.vimp[[j]] - base.obj$holdout.vimp[[j]], na.rm = TRUE)
              }
              else {
                  NA
              }
          })
          names(hvimp) <- names(base.obj$holdout.vimp)
      }
      else if (class(base.obj)[3] == "class") {
          yval <- levels(base.obj$yvar)
          hvimp <- do.call(rbind, lapply(1:length(base.obj$holdout.vimp), function(j) {
              if (!is.null(dim(base.obj$holdout.vimp[[j]]))) {
                  rowMeans(hold.obj$holdout.vimp[[j]] - base.obj$holdout.vimp[[j]], na.rm = TRUE)
              }
              else {
                  rep(NA, length(yval) + 1)
              }
          }))
          colnames(hvimp) <- c("all", yval)
          rownames(hvimp) <- names(base.obj$holdout.vimp)
      }
      else if (class(base.obj)[3] == "surv") {
          hvimp <- sapply(1:length(base.obj$holdout.vimp), function(j) {
              if (!is.null(base.obj$holdout.vimp[[j]])) {
                  mean(hold.obj$holdout.vimp[[j]] - base.obj$holdout.vimp[[j]], na.rm = TRUE)
              }
              else {
                  rep(NA)
              }
          })
          names(hvimp) <- names(base.obj$holdout.vimp)
      }
      else if (class(base.obj)[3] == "surv-CR") {
          hvimp <- do.call(rbind, lapply(1:length(base.obj$holdout.vimp), function(j) {
              if (!is.null(dim(base.obj$holdout.vimp[[j]]))) {
                  rowMeans(hold.obj$holdout.vimp[[j]] - base.obj$holdout.vimp[[j]], na.rm = TRUE)
              }
              else {
                  rep(NA, length(base.obj$holdout.vimp))
              }
          }))
          colnames(hvimp) <- paste("event.", 1:length(get.event.info(base.obj)$event.type), sep = "")
          rownames(hvimp) <- names(base.obj$holdout.vimp)
      }
      rO <- list()
      if (mv.flag) {
          rO$baseline <- rO$holdout <- rO$importance <- list()
          if (length(base.obj$regrOutput) > 0) {
              rO$baseline$regrOutput <- lapply(base.obj$regrOutput, function(o) {
                  o$holdout.vimp
              })
              rO$holdout$regrOutput <- lapply(hold.obj$regrOutput, function(o) {
                  o$holdout.vimp
              })
              rO$importance$regrOutput <- hvimp$regrOutput
          }
          if (length(base.obj$classOutput) > 0) {
              rO$baseline$classOutput <- lapply(base.obj$classOutput, function(o) {
                  o$holdout.vimp
              })
              rO$holdout$classOutput <- lapply(hold.obj$classOutput, function(o) {
                  o$holdout.vimp
              })
              rO$importance$classOutput <- hvimp$classOutput
          }
      }
      else {
          rO$baseline <- base.obj$holdout.vimp
          rO$holdout <- hold.obj$holdout.vimp
          rO$importance <- hvimp
      }
      return(invisible(rO))
  }
  get.partial.bits <- function(partial.length) {
      if (!is.null(partial.length)) {
          if (partial.length > 0) {
              bits <- 2^14
          }
          else if (partial.length == 0) {
              bits <- 0
          }
          else {
              stop("Invalid choice for 'partial.length' option:  ", partial.length)
          }
      }
      else {
          stop("Invalid choice for 'partial.length' option:  ", partial.length)
      }
      return(bits)
  }
