  assign.impute.mean <- function(data, impute.mean) {
      cn <- colnames(data)
      p <- length(cn)
      out <- vector("list", p)
      names(out) <- cn
      for (j in seq_len(p)) {
          nm <- cn[j]
          x <- data[[nm]]
          na_idx <- is.na(x)
          if (any(na_idx)) {
              x[na_idx] <- impute.mean[[nm]]
          }
          out[[j]] <- x
      }
      data.frame(out, row.names = rownames(data), stringsAsFactors = TRUE, check.names = FALSE)
  }
  ginverse <- function(X, tol = sqrt(.Machine$double.eps), test = FALSE) {
      X <- as.matrix(X)
      if (nrow(X) >= ncol(X)) {
          Xinv <- ginverse.workhorse(X, tol)
      }
      else {
          Xinv <- t(ginverse.workhorse(t(X), tol))
      }
      if (test) {
          p1 <- summary(c(X %*% Xinv %*% X - X))
          p2 <- summary(c(Xinv %*% X %*% Xinv - Xinv))
          p3 <- summary(c(X %*% Xinv - t(X %*% Xinv)))
          cat("test 3 properties of generalized inverse:\n")
          print(p1)
          print(p2)
          print(p3)
      }
      Xinv
  }
  km_censor_fit <- function(time, status) {
      stopifnot(length(time) == length(status))
      ok <- !is.na(time) & !is.na(status)
      time <- as.numeric(time[ok])
      status <- as.integer(status[ok])
      n <- length(time)
      if (n == 0L) 
          stop("No non-missing training outcomes.")
      ord <- order(time)
      t <- time[ord]
      s <- status[ord]
      times <- numeric(n)
      G <- numeric(n)
      surv <- 1
      n_risk <- n
      k <- 0L
      i <- 1L
      while (i <= n) {
          ti <- t[i]
          j <- i
          d_death <- 0L
          d_cens <- 0L
          while (j <= n && t[j] == ti) {
              if (s[j] == 1L) 
                  d_death <- d_death + 1L
              else d_cens <- d_cens + 1L
              j <- j + 1L
          }
          n_after_death <- n_risk - d_death
          if (d_cens > 0L) {
              if (n_after_death <= 0L) {
                  surv <- 0
              }
              else {
                  surv <- surv * (1 - d_cens/n_after_death)
              }
          }
          k <- k + 1L
          times[k] <- ti
          G[k] <- surv
          n_risk <- n_risk - (d_death + d_cens)
          i <- j
      }
      list(time = times[1L:k], G = G[1L:k])
  }
