  uno_choose_gmin_auto <- function(G_event, eps = 1e-12, ess_frac = 0.2, ess_min = 20L) {
      g <- as.numeric(G_event)
      g <- g[is.finite(g) & !is.na(g)]
      d <- length(g)
      if (d <= 1L) {
          return(list(gmin = 0, ess_target = NA_real_, ess_kept = NA_real_, n_events = d, n_dropped = 0L, 
              wmax_kept = NA_real_))
      }
      if (min(g) >= 1 - 1e-12) {
          return(list(gmin = 0, ess_target = d, ess_kept = d, n_events = d, n_dropped = 0L, wmax_kept = 1))
      }
      g_sorted <- sort(g)
      w_desc <- 1/pmax(g_sorted, eps)^2
      p1 <- c(0, cumsum(w_desc))
      p2 <- c(0, cumsum(w_desc * w_desc))
      ess_target <- max(as.integer(ess_min), as.integer(ceiling(ess_frac * d)))
      ess_target <- min(ess_target, d)
      best_k <- 0L
      best_ess <- NA_real_
      for (k in 0L:(d - ess_target)) {
          sum_w <- p1[d + 1L] - p1[k + 1L]
          sum_w2 <- p2[d + 1L] - p2[k + 1L]
          ess_k <- if (sum_w2 > 0) 
              (sum_w * sum_w)/sum_w2
          else NA_real_
          if (is.finite(ess_k) && (ess_k >= ess_target)) {
              best_k <- k
              best_ess <- ess_k
              break
          }
      }
      if (!is.finite(best_ess)) {
          best_k <- d - ess_target
          sum_w <- p1[d + 1L] - p1[best_k + 1L]
          sum_w2 <- p2[d + 1L] - p2[best_k + 1L]
          best_ess <- if (sum_w2 > 0) 
              (sum_w * sum_w)/sum_w2
          else NA_real_
      }
      gmin <- g_sorted[best_k + 1L]
      wmax <- 1/pmax(gmin, eps)^2
      list(gmin = gmin, ess_target = ess_target, ess_kept = best_ess, n_events = d, n_dropped = best_k, 
          wmax_kept = wmax)
  }
