  get.holdout.specs <- function(vtry, p, ntree, block.size, mode) {
      if (!is.list(vtry)) {
          if (vtry > 0) {
              holdout <- make.holdout.array(vtry, p, ntree, NULL)
          }
          else {
              stop("vtry must be positive")
          }
      }
      else {
          xvar <- unlist(vtry[1])
          joint <- unlist(vtry[2])
          if (!joint) {
              vtry <- 1
          }
          else {
              vtry <- length(xvar)
          }
          if (!joint) {
              holdout <- do.call(cbind, lapply(1:ntree, function(b) {
                  ho <- rep(0, p)
                  ho[resample(xvar, size = 1, replace = FALSE)] <- 1
                  ho
              }))
          }
          else {
              holdout <- matrix(0, p, ntree)
              holdout[xvar, ] <- 1
          }
      }
      obj <- list(as.integer(vtry), as.integer(holdout), as.integer(block.size), as.integer(0))
      names(obj) = c("vtry", "holdout", "block.size", "mode")
      return(switch.holdout.specs(obj, mode))
  }
  switch.holdout.specs <- function(obj, mode) {
      if (mode == "baseline") {
          new.mode = 1
      }
      else if (mode == "holdout") {
          new.mode = 2
      }
      else if (mode == "natural") {
          new.mode = 3
      }
      else {
          stop("vtry mode invalid")
      }
      obj$mode = as.integer(new.mode)
      return(obj)
  }
  ginverse.workhorse <- function(X, tol) {
      Xsvd <- svd(X)
      Positive <- Xsvd$d > max(tol * Xsvd$d[1L], 0)
      if (all(Positive)) {
          Xsvd$v %*% (1/Xsvd$d * t(Xsvd$u))
      }
      else if (!any(Positive)) {
          array(0, dim(X)[2L:1L])
      }
      else {
          Xsvd$v[, Positive, drop = FALSE] %*% ((1/Xsvd$d[Positive]) * t(Xsvd$u[, Positive, drop = FALSE]))
      }
  }
  get.event.info <- function(obj, subset = NULL) {
      if (grepl("surv", obj$family)) {
          if (!is.null(obj$yvar)) {
              if (is.null(subset)) {
                  subset <- (1:nrow(cbind(obj$yvar)))
              }
              if (is.null(obj$subj)) {
                  r.dim <- 2
                  time <- obj$yvar[subset, 1]
                  cens <- obj$yvar[subset, 2]
              }
              else {
                  r.dim <- 3
                  start.time <- obj$yvar[subset, 1]
                  time <- obj$yvar[subset, 2]
                  cens <- obj$yvar[subset, 3]
              }
              if (!all(floor(cens) == abs(cens), na.rm = TRUE)) {
                  stop("for survival families censoring variable must be coded as a non-negative integer")
              }
              event <- na.omit(cens)[na.omit(cens) > 0]
              event.type <- sort(unique(event))
          }
          else {
              r.dim <- 0
              event <- event.type <- cens <- cens <- time <- NULL
          }
          time.interest <- obj$time.interest
      }
      else {
          if ((obj$family == "regr+") | (obj$family == "class+")) {
              r.dim <- dim(obj$yvar)[2]
          }
          else {
              r.dim <- 1
          }
          event <- event.type <- cens <- time.interest <- cens <- time <- NULL
      }
      return(list(event = event, event.type = event.type, cens = cens, time.interest = time.interest, time = time, 
          r.dim = r.dim))
  }
  .km.censor.predict <- function(time_knots, G, t_new, type = c("left", "right")) {
      type <- match.arg(type)
      t_new <- as.numeric(t_new)
      out <- rep(NA_real_, length(t_new))
      ok <- !is.na(t_new)
      if (!any(ok)) 
          return(out)
      if (length(time_knots) == 0L) {
          out[ok] <- 1
          return(out)
      }
      idx <- if (type == "left") {
          findInterval(t_new[ok], time_knots, left.open = TRUE)
      }
      else {
          findInterval(t_new[ok], time_knots)
      }
      out[ok] <- c(1, G)[1L + idx]
      out
  }
  get.uno.weights.test <- function(time_test, fit, eps = 1e-12, drop_if_G0 = FALSE) {
      if (is.null(fit$time) || is.null(fit$G)) 
          stop("fit must be a list with elements $time and $G")
      gmin_used <- if (!is.null(fit$gmin) && is.finite(fit$gmin)) 
          fit$gmin
      else 0
      eps_keep <- if (!is.null(fit$eps_keep) && is.finite(fit$eps_keep)) 
          fit$eps_keep
      else .Machine$double.eps
      G_gate <- uno_Ghat_minus_predict(fit$time, fit$G, time_test)
      w <- rep(0, length(time_test))
      ok <- !is.na(G_gate)
      if (!drop_if_G0) {
          keep <- ok & (G_gate >= gmin_used)
      }
      else {
          keep <- ok & (G_gate >= gmin_used) & (G_gate > eps)
      }
      drop <- ok & !keep
      if (any(keep)) {
          Gsafe <- pmax(G_gate[keep], eps)
          w[keep] <- 1/(Gsafe * Gsafe)
      }
      if (any(drop)) {
          w[drop] <- eps_keep
      }
      w
  }
  partial.rfsrc <- function(object, oob = TRUE, partial.type = NULL, partial.xvar = NULL, partial.values = NULL, 
      partial.xvar2 = NULL, partial.values2 = NULL, partial.time = NULL, get.tree = NULL, seed = NULL, 
      do.trace = FALSE, ...) {
      user.option <- list(...)
      if (missing(object)) {
          stop("object is missing!")
      }
      if (sum(inherits(object, c("rfsrc", "grow"), TRUE) == c(1, 2)) != 2 & sum(inherits(object, c("rfsrc", 
          "forest"), TRUE) == c(1, 2)) != 2) {
          stop("this function only works for objects of class `(rfsrc, grow)' or '(rfsrc, forest)'")
      }
      if (inherits(object, "anonymous")) {
          stop("this function does not work with anonymous forests")
      }
      jitt <- is.hidden.jitt(user.option, "none", "na.omit", FALSE, partial = TRUE)
      data.pass <- is.hidden.data.pass(user.option)
      if (sum(inherits(object, c("rfsrc", "grow"), TRUE) == c(1, 2)) == 2) {
          if (is.forest.missing(object)) {
              stop("The forest is empty.  Re-run rfsrc (grow call) with forest=TRUE")
          }
          object <- object$forest
      }
      else {
      }
      if (!is.logical(oob) || length(oob) != 1L || is.na(oob)) {
          stop("'oob' must be TRUE or FALSE")
      }
      if (oob) {
          ensemble <- "oob"
      }
      else {
          ensemble <- "inbag"
      }
      family <- object$family
      splitrule <- object$splitrule
      xvar.names <- object$xvar.names
      yvar.names <- object$yvar.names
      if (!is.character(partial.xvar) || length(partial.xvar) != 1L || is.na(partial.xvar) || !(partial.xvar %in% 
          xvar.names)) {
          stop("'partial.xvar' must name one predictor in the forest")
      }
      .partial.check.values(partial.values, partial.xvar, object)
      partial.values <- sort(unique(partial.values))
      if (length(partial.xvar2) || length(partial.values2)) {
          if (!is.character(partial.xvar2) || anyNA(partial.xvar2) || anyDuplicated(partial.xvar2) || any(!(partial.xvar2 %in% 
              xvar.names)) || partial.xvar %in% partial.xvar2 || length(partial.xvar2) != length(partial.values2)) {
              stop("secondary predictors must be distinct forest predictors, different ", "from 'partial.xvar', with one value for each predictor")
          }
          for (i in seq_along(partial.xvar2)) {
              .partial.check.values(partial.values2[i], partial.xvar2[i], object)
          }
      }
      if (family %in% c("surv", "surv-CR")) {
          allowed <- if (family == "surv") 
              c("mort", "rel.freq", "surv", "chf")
          else c("years.lost", "cif", "chf")
          if (!is.character(partial.type) || length(partial.type) != 1L || is.na(partial.type)) {
              stop("specify one 'partial.type': ", paste(allowed, collapse = ", "))
          }
          partial.type <- match.arg(partial.type, allowed)
      }
      else if (grepl("surv", family)) {
          stop("this survival family is not supported by partial()")
      }
      yfactor <- object$yvar.factor
      m.target.idx <- 1:length(yvar.names)
      yvar.types <- yfactor$types
      yvar.nlevels <- yfactor$nlevels
      yvar.numeric.levels <- yfactor$numeric.levels
      subj <- object$subj
      event.info <- object$event.info
      event.type <- event.info$event.type
      partial.time.idx <- NULL
      if (family %in% c("surv", "surv-CR") && partial.type %in% c("surv", "cif", "chf")) {
          partial.time.idx <- .partial.time.index(partial.time, event.info$time.interest)
      }
      cr.bits <- get.cr.bits(family)
      xfactor <- object$xvar.factor
      xvar.types <- xfactor$types
      xvar.nlevels <- xfactor$nlevels
      xvar.numeric.levels <- xfactor$numeric.levels
      ntree <- object$ntree
      na.action = object$na.action
      xvar <- as.matrix(data.matrix(object$xvar))
      yvar <- as.matrix(data.matrix(object$yvar))
      r.dim <- ncol(cbind(yvar))
      rownames(xvar) <- colnames(xvar) <- NULL
      n.xvar <- ncol(xvar)
      n <- nrow(xvar)
      sampsize <- round(object$sampsize(n))
      case.wt <- object$case.wt
      samp <- object$samp
      outcome = "train"
      get.tree <- get.tree.index(get.tree, ntree)
      ensemble.bits <- get.ensemble.bits(ensemble)
      bootstrap.bits <- get.bootstrap.bits(object$bootstrap)
      na.action.bits <- get.na.action.bits(na.action)
      samptype.bits <- get.samptype.bits(object$samptype)
      partial.bits <- get.partial.bits(length(partial.values))
      terminal.qualts.bits <- get.terminal.qualts.predict.bits(object$terminal.qualts)
      terminal.quants.bits <- get.terminal.quants.predict.bits(object$terminal.quants)
      data.pass.bits <- get.data.pass.bits(data.pass)
      jitt.bits <- get.jitt.bits(jitt)
      seed <- get.seed(seed)
      do.trace <- get.trace.bits(do.trace)
      pivot = 0
      chunk = 0
      nativeOutput <- tryCatch({
          .Call("sl_rfsrcPredict", as.integer(do.trace), as.integer(seed), as.integer(ensemble.bits + bootstrap.bits + 
              cr.bits), as.integer(samptype.bits + na.action.bits + terminal.qualts.bits + terminal.quants.bits + 
              partial.bits + data.pass.bits + jitt.bits), as.numeric(1), as.integer(ntree), as.integer(n), 
