              surv.names <- list(NULL, NULL, NULL)
              survOutput <- (if (!is.null(nativeOutput$partialSurv)) 
                  array(nativeOutput$partialSurv, c(n, length(event.info$time.interest), length(partial.values)), 
                    dimnames = surv.names)
              else NULL)
              if (!is.null(survOutput)) {
